mod registry;
mod selection;

use clap::{Parser, Subcommand};
use registry::{Artifact, ArtifactKind, load_registry};
use selection::resolve_selection;

#[derive(Parser)]
#[command(name = "install-ctl", about = "Install workspace tool binaries and extensions")]
struct Cli {
    /// Print supported artifacts grouped by category and exit.
    #[arg(long)]
    list: bool,

    /// Print the planned actions without performing them.
    #[arg(long)]
    dry_run: bool,

    #[command(subcommand)]
    command: Option<Command>,
}

#[derive(Subcommand)]
enum Command {
    /// Install one or more artifacts by id, category, or "all".
    Install {
        #[arg(required = true)]
        selection: Vec<String>,
    },
}

fn main() {
    let cli = Cli::parse();

    if cli.list {
        match load_registry() {
            Ok(reg) => print_list(&reg.artifacts),
            Err(e) => fail(&e),
        }
        return;
    }

    match cli.command {
        Some(Command::Install { selection }) => {
            let reg = match load_registry() {
                Ok(reg) => reg,
                Err(e) => fail(&e),
            };
            let selected = match resolve_selection(&reg.artifacts, &selection) {
                Ok(s) => s,
                Err(e) => fail(&e),
            };
            if selected.is_empty() {
                fail("selection matched no artifacts");
            }
            if cli.dry_run {
                print_plan(&selected);
            } else {
                run_install(&selected);
            }
        }
        None => {
            eprintln!("error: no command given; try --list or `install <selection>`");
            std::process::exit(1);
        }
    }
}

fn print_list(artifacts: &[Artifact]) {
    let mut categories: Vec<&str> = artifacts.iter().map(|a| a.category.as_str()).collect();
    categories.sort();
    categories.dedup();

    for category in categories {
        println!("{category}:");
        for artifact in artifacts.iter().filter(|a| a.category == category) {
            println!("  {}", artifact.id);
        }
    }
}

fn print_plan(selected: &[Artifact]) {
    for artifact in selected {
        match artifact.kind {
            ArtifactKind::RustBinary => {
                let bin = artifact.bin.as_deref().unwrap_or(&artifact.id);
                println!("==> {}", artifact.id);
                println!(
                    "    cargo install --path \"{}\" --bin {} --force",
                    artifact.path, bin
                );
            }
            ArtifactKind::VscodeExtension => {
                let script = artifact.npm_script.as_deref().unwrap_or("install:vsix");
                println!("==> {}", artifact.id);
                println!("    (cd \"{}\" && npm ci && npm run {})", artifact.path, script);
            }
        }
    }
}

fn run_install(selected: &[Artifact]) {
    eprintln!(
        "error: real installation is not yet wired up in install-ctl ({} artifact(s) selected); \
         use --dry-run to preview, or fall back to install-tools.sh / install-extensions.sh",
        selected.len()
    );
    std::process::exit(1);
}

fn fail(message: &str) -> ! {
    eprintln!("error: {message}");
    std::process::exit(1);
}

use crate::registry::Artifact;

/// Mirrors install-tools.sh's selection semantics: `all`, a single artifact
/// id, or a whole category name; comma-separated tokens are also accepted.
pub fn resolve_selection(artifacts: &[Artifact], tokens: &[String]) -> Result<Vec<Artifact>, String> {
    let mut selected: Vec<Artifact> = Vec::new();

    let mut push = |artifact: &Artifact, selected: &mut Vec<Artifact>| {
        if !selected.iter().any(|s| s.id == artifact.id) {
            selected.push(artifact.clone());
        }
    };

    for raw in tokens {
        for token in raw.split(',') {
            let token = token.trim();
            if token.is_empty() {
                continue;
            }

            if token == "all" {
                for artifact in artifacts {
                    push(artifact, &mut selected);
                }
                continue;
            }

            if let Some(artifact) = artifacts.iter().find(|a| a.id == token) {
                push(artifact, &mut selected);
                continue;
            }

            let category_matches: Vec<&Artifact> =
                artifacts.iter().filter(|a| a.category == token).collect();
            if !category_matches.is_empty() {
                for artifact in category_matches {
                    push(artifact, &mut selected);
                }
                continue;
            }

            return Err(format!("unknown artifact or category: {token}"));
        }
    }

    Ok(selected)
}

